_mask = np.max(np.abs({waveform}), axis=-1) > {threshold} if {waveform}.ndim > 1 else np.abs({waveform}) > {threshold}
_idx = np.where(_mask)[0]
{trimmed_waveform} = {waveform}[_idx[0]:_idx[-1] + 1] if len(_idx) > 0 else {waveform}[:0]

_pcm = np.clip({waveform}, -1.0, 1.0)
_pcm_16 = (_pcm * 32767).astype(np.int16) if np.issubdtype({waveform}.dtype, np.floating) else {waveform}
wavfile.write({filepath}, {sample_rate}, _pcm_16)
